fn square_nums(nums: &Vec<i32>) -> Vec<i32> {
    // Create a new vector to hold the squared values
    let mut squared: Vec<i32> = Vec::with_capacity(nums.len());
    
    // Iterate over each number in the input vector
    for &num in nums.iter() {
        // Calculate the square and push it to the squared vector
        squared.push(num * num);
    }
    
    // Return the new vector containing squared values
    squared
}